it('rejects wrong-typed fields naming the field and expected type without leaking values', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'test',
      description: 'test',
      inputSchema: {
        type: 'object',
        properties: {count: {type: 'number'}},
      },
    },
    async () => 'ok'
  );

  const response = await registry.execute('test', {count: 'secret-value'});
  expect({
    result: response.result,
    containsValue: response.result.includes('secret-value'),
  }).toMatchObject({
    result: expect.stringMatching(/(count|root).*(number)/),
    containsValue: false,
  });
});

