it('validates function-valued tool definitions against the current schema and caches it', async () => {
  const registry = new ToolRegistry();
  const schema1 = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};
  const schema2 = {type: 'object', properties: {b: {type: 'number'}}, required: ['b']};
  let currentSchema: Record<string, unknown> = schema1;

  registry.register(
    () => ({name: 'fn', description: 'd', inputSchema: currentSchema}),
    async () => 'ok'
  );

  // First call with schema1
  const res1 = await registry.execute('fn', {a: 'val'});
  const res1Fail = await registry.execute('fn', {});
  expect(res1.result).toBe('ok');
  expect(res1Fail.result).toContain("must have required property 'a'");

  // Switch to schema2
  currentSchema = schema2;
  const res2 = await registry.execute('fn', {b: 123});
  const res2Fail = await registry.execute('fn', {a: 'val'});
  expect(res2.result).toBe('ok');
  expect(res2Fail.result).toContain("must have required property 'b'");

  // @ts-expect-error - accessing private ajv to spy on compile
  const spy = jest.spyOn(registry.ajv, 'compile');
  await registry.execute('fn', {b: 456}); // Should use cached schema2

  expect(spy).not.toHaveBeenCalled();
  spy.mockRestore();
});

